INSERT INTO `digitalpdf$script` (`Id`,`Name`,`Commands`,`ModificationTimeUtc`,`IsDeleted`) VALUES (9999,'JajaFinance_CreditCard','$source = \"Jaja Finance\"\n$features = \"NO_TRANSACTION_YEAR CREDIT_CARD SKIP_MISSING_CLOSING_BALANCE_CHECK\"\n\n// Delete the blank page 4 and the Useful Information page\ndelete all pages containing \"Useful Information\"\n\ngo to page 1\n\n// Get account number\n$accountNumber = get line containing \"Account number:\" => take last words 1 => get text\n\n// Get account name\n$accountName = get line starting \"MISS\" => take words 3 => get text\n\n// Get period to (statement date)\n$periodTo = get line containing \"Statement date:\" => take last words 3 => get date \"d MMM yyyy\"\n\n// Get period from - derived from the earliest transaction date; use statement date minus ~1 month approximation\n// The statement covers approximately one month; use opening balance line date logic\n// periodFrom: look for the first transaction date in the table - use the previous balance line as anchor\n// We will set periodFrom from the \"Payment due\" date line context - not available directly\n// Use the first transaction posting date visible: 29 Apr -> so period starts ~28 Apr\n// Best approach: get periodFrom from the date of the first transaction line\ngo to page 1\n@prevBalLine = get line containing \"Previous Balance\" => bottom => get line below => bottom => get line below\n$periodFrom = get text in box page.top @prevBalLine 0 80 => take words 2 => get date \"d MMM\"\n\n// Get opening balance (previous statement balance)\n$openingBalance = get line containing \"Statement balance last month\" => take last words 1 => get decimal\n\n// Get closing balance (outstanding statement balance)\n$closingBalance = get line containing \"Outstanding statement balance\" => take last words 1 => get decimal\n\n// Delete the left-hand panel text on page 1 that interferes with table extraction\n@summaryTop = get line containing \"Summary\" => top\ndelete text in box page.top @summaryTop page.left page.middleX\n\n// Delete the summary block above the transactions\n@yourTransTop = get line containing \"Your Transactions\" => top\ndelete text in box page.top @yourTransTop page.left page.right\n\n// Remove the header row and account name row that appear at the top of the transaction table\ndelete all lines containing \"Transaction Posting\"\ndelete all lines containing \"Date Date Description\"\ndelete all lines containing \"Previous Balance\"\ndelete all lines starting \"MISS \"\ndelete all lines starting \"Continued on the next page\"\ndelete all lines starting \"Your Transactions\"\n\n// Remove totals and interest lines that appear within/below the transaction list\ndelete all lines starting \"Total for new transactions\"\ndelete all lines starting \"Total payments and credits\"\ndelete all lines starting \"Interest charged on\"\ndelete all lines starting \"Outstanding balance\"\n\n// Discard page footer\nignore footer below 50\n\n// Get start of table on page 1\ngo to page 1\n@transactionsTop = get line containing \"Your Transactions\" => bottom => get line below => bottom => get line below => bottom => get line below\n\n// Get end of table on last page\ngo to last page\n@transactionsBottom = get line starting \"Total for new transactions\" => top => get line above\n\n// Read the transactions across all pages\n// Columns: TransactionDate | PostingDate | Description | Amount\n// Approximate X positions based on layout:\n//   Transaction Date: ~230-290, Posting Date: ~290-350, Description: ~350-530, Amount: ~530-right\n$transactions = get multi page table @transactionsTop @transactionsBottom 230 290 350 530 page.right => describe table false \"*Date[dd MMM]\" - Details #Credit\n',UTC_TIMESTAMP(),0);
INSERT INTO `digitalpdf$documentidentification` (`Id`,`Name`,`TitlePattern`,`AuthorPattern`,`CreatorPattern`,`ProducerPattern`,`Version`,`PageCount`,`SignatureInfo`,`ContainsText`,`ExcludesText`,`ScriptId`,`VerificationRuleSetId`,`ModificationTimeUtc`,`IsDeleted`) VALUES (9999,'JajaFinance_CreditCard',NULL,NULL,'^$',NULL,NULL,NULL,NULL,'[\"Your credit card statement\",\"jaja.co.uk\",\"Statement balance last month\",\"Outstanding statement balance\"]',NULL,9999,4,UTC_TIMESTAMP(),0);
